const MASK = (1n<<64n)-1n;
function hash1(bytes, seed, K){
  let acc = seed;
  for (const b of bytes){
    acc = (acc ^ BigInt(b)) & MASK;
    acc = (acc * K) & MASK;
  }
  return acc;
}
function twoRound(bytes, s1,k1,s2,k2){
  const r1 = hash1(bytes, s1, k1);
  const s2x = (s2 ^ r1) & MASK;
